'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var hasProp = require( '@stdlib/assert/has-property' );
var isObject = require( '@stdlib/assert/is-object' );
var Title = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Title, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `encode` property', function test( t ) {
	var v;

	v = new Title();
	t.strictEqual( hasOwnProp( v, 'encode' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'encode' ), true, 'returns expected value' );
	t.strictEqual( isUndefined( v.encode ), true, 'returns expected value' );

	v = new Title({
		'encode': {
			'title': {
				'enter': {
					'fill': {
						'value': 'steelblue'
					}
				}
			}
		}
	});
	t.strictEqual( isObject( v.encode ), true, 'returns expected value' );

	t.end();
});

tape( 'the constructor throws an error if provided an invalid `encode` option', function test( t ) {
	var values;
	var i;

	values = [
		5,
		'beep',
		'boop',
		NaN,
		null,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title({ // eslint-disable-line no-unused-vars
				'encode': value
			});
		};
	}
});

tape( 'the constructor returns an instance having a `encode` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		5,
		'beep',
		'boop',
		NaN,
		null,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title();
			title.encode = value;
		};
	}
});

tape( 'the constructor returns an instance having a `encode` property', function test( t ) {
	var expected;
	var title;

	title = new Title();
	t.strictEqual( isUndefined( title.encode ), true, 'returns expected value' );

	title = new Title({
		'encode': {
			'title': {
				'enter': {
					'fill': {
						'value': 'steelblue'
					}
				}
			}
		}
	});

	expected = {
		'encode': {
			'title': {
				'enter': {
					'fill': {
						'value': 'steelblue'
					}
				}
			}
		}
	};
	t.deepEqual( title.encode, expected.encode, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `encode` property which can be set to a valid method', function test( t ) {
	var expected;
	var title;

	title = new Title();

	title.encode = {
		'title': {
			'enter': {
				'fill': {
					'value': 'steelblue'
				}
			}
		}
	};

	expected = {
		'encode': {
			'title': {
				'enter': {
					'fill': {
						'value': 'steelblue'
					}
				}
			}
		}
	};
	t.deepEqual( title.encode, expected.encode, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `encode` property is set to a new value', function test( t ) {
	var title;
	var count;
	var obj1;
	var obj2;

	title = new Title();
	count = 0;

	title.on( 'change', onChange );

	obj1 = {
		'title': {
			'enter': {
				'fill': {
					'value': 'steelblue'
				}
			}
		}
	};
	title.encode = obj1;
	t.strictEqual( count, 1, 'returns expected value' );

	obj2 = {
		'title': {
			'enter': {
				'fill': {
					'value': 'red'
				}
			}
		}
	};
	title.encode = obj2;
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	title.encode = obj2;
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
